<?php
namespace App\Services\Dapcode; use Illuminate\Support\Facades\File; use Illuminate\Support\Facades\Log; class LicenseAuditLogger { public static function log(array $params) : void { $payload = [ 'timestamp' => $params['timestamp'] ?? date('c'), 'module_id' => $params['module_id'] ?? 'all', 'module_name' => $params['module_name'] ?? ( ! empty($params['module_id']) ? ucfirst((string) $params['module_id']) : 'System'), 'action' => $params['action'] ?? 'UNKNOWN', 'previous_license_status' => $params['previous_license_status'] ?? 'unknown', 'new_license_status' => $params['new_license_status'] ?? 'unknown', 'source_state' => $params['source_state'] ?? 'unknown', 'trigger' => $params['trigger'] ?? 'system', 'calling_class' => $params['calling_class'] ?? '', 'calling_method' => $params['calling_method'] ?? '', ]; Log::info('[AUDIT] EVENT: ' . $payload['action'], $payload); } public static function detectSourceState( ? string $filePath) : string { if ( ! $filePath || ! File::isFile($filePath)) { return 'unknown'; } $content = File::get($filePath); $lines = substr_count($content, "\n") + 1; $size = strlen($content); $avgLineLen = $size / max(1, $lines); $isMinified = ($lines <= 3 && $size > 100) || ($lines <= 10 && $size > 2000 && $avgLineLen > 250); return $isMinified ? 'minified' : 'original'; } }